Records ``(entry_id, value)`` entries such that each entry id is applied
AT MOST ONCE. Re-applying a known id is a no-op that returns ``False``.
"""


class Journal:
    """A journal in which each entry id is accepted at most once."""

    def __init__(self) -> None:
        self._entries: dict[str, int] = {}
        self._total: int = 0

    @staticmethod
    def _validate(entry_id: str, value: int) -> None:
        if not isinstance(entry_id, str) or not entry_id.strip():
            raise ValueError(
                "entry_id must be a non-empty (and non-whitespace) str"
            )
        # bool is a subclass of int and must be explicitly rejected.
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("value must be an int (bool is not accepted)")

    def apply(self, entry_id: str, value: int) -> bool:
        """Record ``value`` under ``entry_id`` unless it was already applied.

        Returns ``True`` if the entry was stored, ``False`` if ``entry_id``
        had already been applied (in which case total and count are
        unchanged). Raises ``ValueError`` for an invalid ``entry_id`` or
        ``value``.
        """
        self._validate(entry_id, value)
        if entry_id in self._entries:
            return False
        self._entries[entry_id] = value
        self._total += value
        return True

    def total(self) -> int:
        """Sum of the values of all accepted entries."""
        return self._total

    def count(self) -> int:
        """Number of accepted entries."""
        return len(self._entries)
